{
  "path": "worker/pool.go",
  "size": 614,
  "content": "package worker

import "sync"

// Pool runs jobs on n goroutines and collects their results.
type Pool struct {
	jobs    chan func() int
	results chan int
	wg      sync.WaitGroup
}

func New(n int) *Pool {
	p := &Pool{jobs: make(chan func() int), results: make(chan int)}
	for i := 0; i < n; i++ {
		p.wg.Add(1)
		go func() {
			defer p.wg.Done()
			for job := range p.jobs {
				p.results <- job()
			}
		}()
	}
	return p
}

func (p *Pool) Submit(job func() int) { p.jobs <- job }

func (p *Pool) Results() <-chan int { return p.results }

func (p *Pool) Close() {
	close(p.jobs)
	p.wg.Wait()
	close(p.results)
}
"
